static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }

    // Normalize the supplied name to eliminate ".." and separator characters
    // Use Path to resolve any relative components.
    Path normalizedPath = Paths.get(name).normalize();

    // Reject any path that is not a simple file name (contains separators or "..")
    if (normalizedPath.getNameCount() != 1) {
        throw new IllegalArgumentException("Invalid file name: path traversal components are not allowed");
    }

    String safeName = normalizedPath.getFileName().toString();

    // Ensure the resulting file stays inside the intended directory
    File file = new File(dir, safeName);
    try {
        Path dirPath = dir.getCanonicalFile().toPath();
        Path filePath = file.getCanonicalFile().toPath();
        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException("Resulting file is outside the target directory");
        }
    } catch (IOException e) {
        throw new UncheckedIOException("Failed to resolve canonical paths", e);
    }

    // Duplicate handling
    int dot = safeName.lastIndexOf('.');
    String prefix = dot < 0 ? safeName : safeName.substring(0, dot);
    String suffix = dot < 0 ? "" : safeName.substring(dot);
    int index = 2;
    while (file.exists()) {
        file = new File(dir, prefix + "-" + index++ + suffix);
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}
