import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.core.io.Resource;
import org.springframework.util.FileCopyUtils;

/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>Previous implementations accepted an external seed via {@code Resource}
 * and called {@link SecureRandom#setSeed(byte[])}. Supplying a predictable
 * seed undermines the cryptographic strength of the generator. This
 * implementation no longer uses external seed data; it relies on the
 * platform‑provided entropy sources.</p>
 *
 * <p>If a seed resource is configured, a warning is logged and the seed is
 * ignored. The {@code algorithm} property is retained for backward
 * compatibility but is only used when the strong instance cannot be obtained.
 * </p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private static final Logger logger = Logger.getLogger(SecureRandomFactoryBean.class.getName());

    /** Preferred algorithm – retained for compatibility but not mandatory. */
    private String algorithm = "SHA1PRNG";

    /** Optional external seed – will be ignored for security reasons. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // Force early seeding (recommended practice) without using external data.
        rnd.nextBytes(new byte[1]);

        // If a seed resource was supplied, log a warning and discard it.
        if (seed != null) {
            logger.log(Level.WARNING,
                    "SecureRandomFactoryBean: external seed resource is configured but will be ignored for security reasons.");
        }

        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // Each call returns a freshly seeded instance.
        return false;
    }

    // -----------------------------------------------------------------------
    // Configuration setters (used by Spring)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Attempts to obtain a strong {@link SecureRandom} implementation. If the
     * platform does not provide one, falls back to {@link SecureRandom#getInstance(String)}
     * using the configured algorithm, and finally to the no‑arg constructor.
     *
     * @return a securely seeded {@link SecureRandom} instance
     * @throws NoSuchAlgorithmException if the configured algorithm is not available
     */
    private SecureRandom createSecureRandomInstance() throws NoSuchAlgorithmException {
        try {
            // Java 8 provides getInstanceStrong() which selects the strongest
            // algorithm available on the platform.
            return SecureRandom.getInstanceStrong();
        } catch (NoSuchAlgorithmException ex) {
            logger.log(Level.INFO,
                    "SecureRandom.getInstanceStrong() not available; falling back to algorithm [{0}].", algorithm);
            // Fallback to the explicitly configured algorithm.
            return SecureRandom.getInstance(algorithm);
        } catch (Exception ex) {
            // As a last resort, use the default constructor which also performs
            // platform‑specific seeding.
            logger.log(Level.WARNING,
                    "Failed to obtain a strong SecureRandom instance; using default constructor.", ex);
            return new SecureRandom();
        }
    }
}
