private static String normalizePath(final String path) {
    if (path == null) {
        return null;
    }
    // Remove all leading '/' characters
    int index = 0;
    while (index < path.length() && path.charAt(index) == '/') {
        index++;
    }
    // The normalized path must start with a single '/'.
    // If the original string consisted only of '/', return "/".
    if (index == path.length()) {
        return "/";
    }
    String remainder = path.substring(index);
    return "/" + remainder;
}

