     * Regular expression that matches a single, safe JSP page name.
     * <ul>
     *   <li>must start with a forward slash</li>
     *   <li>followed by one or more alphanumeric, underscore or hyphen characters</li>
     *   <li>ending with the literal ".jsp"</li>
     * </ul>
     * This whitelist approach prevents path‑traversal (e.g. "..") and
     * disallows any additional path segments.
     */
    private static final Pattern SAFE_FORWARD_PATTERN =
            Pattern.compile("^/([A-Za-z0-9_-]+)\\.jsp$");

