/**
 * Performs JPEG sign‑extension on the supplied value.
 *
 * <p>The original implementation used a {@code while} loop that recomputed {@code vt}
 * on each iteration, which could lead to an infinite loop when crafted inputs were
 * supplied (e.g., {@code t} not validated).  The JPEG specification defines the
 * operation as a single conditional adjustment, not an iterative process.</p>
 *
 * @param v the raw value read from the bit‑stream (must be in the range
 *          {@code 0 .. (2^t)-1})
 * @param t the number of bits that {@code v} occupies (must be >0 and <=30)
 * @return the signed integer represented by {@code v}
 * @throws IllegalArgumentException if {@code t} or {@code v} are out of the
 *         expected bounds
 */
private int extend(int v, final int t) {
    // Validate bit length – JPEG never uses more than 16 bits, but we keep a
    // safe upper bound to avoid overflow of the shift operations.
    if (t <= 0 || t > 30) {
        throw new IllegalArgumentException("Invalid bit length: " + t);
    }

    // The maximum unsigned value that can be represented with {@code t} bits.
    int maxUnsigned = (1 << t) - 1;
    if (v < 0 || v > maxUnsigned) {
        throw new IllegalArgumentException(
                "Value out of range for the given bit length (v=" + v + ", t=" + t + ')');
    }

    // Threshold for sign detection (2^(t‑1)).
    int vt = 1 << (t - 1);

    // If the most‑significant bit is 0, the value is negative and must be
    // sign‑extended.  The correction term is (-1 << t) + 1, which is equivalent
    // to subtracting 2^t from the unsigned value.
    if (v < vt) {
        v += (-1 << t) + 1;
    }

    return v;
}
