 * Patched implementation of {@code NioZipEncoding.encode(String)} that eliminates the
 * infinite‑loop vulnerability. The method now guarantees forward progress of the
 * {@link CharBuffer} position for every iteration, limits the number of iterations
 * to a sane maximum and correctly grows the output buffer when required.
 */
class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // other methods ...

    private static final int MAX_ITERATIONS = 10_000; // defensive limit

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        CharBuffer tmp = null;                     // reused for surrogate handling
        ByteBuffer out = ByteBuffer.allocate(
                estimateInitialBufferSize(enc, cb.remaining()));

        int iterationCount = 0;                    // protect against pathological input

        while (cb.remaining() > 0) {
            // safeguard against pathological inputs that could otherwise loop forever
            if (++iterationCount > MAX_ITERATIONS) {
                throw new IllegalStateException(
                        "Encoding aborted after too many iterations – possible malformed input");
            }

            final CoderResult res = enc.encode(cb, out, false);

            if (res.isUnmappable() || res.isMalformed()) {
