                 *  causing an infinite loop.  Here we:
                 *   1. Ensure enough space in the output buffer.
                 *   2. Consume the offending characters (advancing cb.position()).
                 *   3. Encode each offending character using the surrogate helper.
                 * ------------------------------------------------------------- */
                int needed = estimateIncrementalEncodingSize(enc, 6 * res.length());
                if (needed > out.remaining()) {
                    out = ZipEncodingHelper.growBufferBy(out, needed - out.remaining());
                }

                if (tmp == null) {
                    tmp = CharBuffer.allocate(6);
                }

