import com.opensymphony.xwork2.util.LocalizedTextUtil;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Interceptor that handles i18n locale resolution.
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Whitelist pattern for locale strings.
     *  Accepts language (2‑3 letters) optionally followed by a country (2 letters)
     *  and an optional variant (alphanumeric). Examples: "en", "en-US", "fr-CA-variant".
     */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2,3}(?:-[a-zA-Z]{2})?(?:-[a-zA-Z0-9]+)?$");

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a strict whitelist to prevent malicious values (e.g., XSS payloads)
     * from being turned into a {@code Locale}.
     *
     * @param requestedLocale the parameter from the request
     * @return a {@code Locale} instance if the input is valid; {@code null} otherwise
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale, trust it – it cannot contain XSS payloads.
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale (already Locale): {}", locale);
            return locale;
        }

        // Convert to String and trim whitespace.
        String localeStr = requestedLocale.toString().trim();

        // Reject empty strings early.
        if (localeStr.isEmpty()) {
            LOG.warn("Requested locale string is empty after trimming.");
            return null;
        }

        // Validate against the whitelist pattern.
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Invalid locale format detected: '{}'. Locale will be ignored.", localeStr);
            return null;
        }

        // At this point the string conforms to the expected pattern; safely create the Locale.
        Locale locale = LocalizedTextUtil.localeFromString(localeStr, null);
        if (locale == null) {
            LOG.warn("Unable to parse a valid Locale from the string: '{}'.", localeStr);
            return null;
        }

        LOG.debug("Applied request locale: {}", locale);
        return locale;
    }

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------
}
