    /** Default safe action name used when the supplied name is invalid. */
    private static final String DEFAULT_ACTION_NAME = "index";

    // other methods

    /**
     * Validates the action name against a whitelist pattern.
     * If the name is valid it is returned unchanged; otherwise a safe default
     * name is returned and a warning is logged.
     *
     * @param rawActionName action name extracted from URI
     * @return a safe action name
     */
    protected String cleanupActionName(final String rawActionName) {
        // Defensive null handling – treat null as invalid input.
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name; using default safe action name [{0}].", DEFAULT_ACTION_NAME);
            }
            return DEFAULT_ACTION_NAME;
        }

        // If the name matches the whitelist pattern, it is considered safe.
        if (allowedActionNames.matcher(rawActionName).matches()) {
            return rawActionName;
        }

        // Name does not conform to the whitelist – reject it and fall back to a safe default.
        if (LOG.isWarnEnabled()) {
            LOG.warn("Action/method [{0}] does not match allowed action names pattern [{1}]; using default safe action name [{2}].",
                    rawActionName, allowedActionNames.pattern(), DEFAULT_ACTION_NAME);
        }

        return DEFAULT_ACTION_NAME;
    }

    // other methods

}
