 * resources (TLS response and LDAP context) are closed on failure.
 *
 * @param ldapContextFactory the factory that provides LDAP connection settings
 * @param principal          the bind DN (or user name) – must not be null/empty
 * @param credentials        the password – must not be null
 * @return an authenticated {@link LdapContext}
 * @throws NamingException   if the bind fails or any LDAP error occurs
 */
private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {
    // ----- 1. Validate caller supplied credentials ---------------------------
    if (principal == null || principal.toString().trim().isEmpty()) {
        throw new IllegalArgumentException("LDAP principal must not be null or empty");
    }
    if (credentials == null) {
        throw new IllegalArgumentException("LDAP credentials must not be null");
    }

