            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e; // remember the failure – we may need to re‑throw it later
            }
        }

        // -----------------------------------------------------------------
        // 2. Fallback handling for common payload forms when the conversion
        //    above did not succeed (answer == null).  We now parse the XML
        //    ourselves using the hardened parser to avoid XXE.
        // -----------------------------------------------------------------
        if (answer == null) {
