                byte[] bytes = ((String) body).getBytes(StandardCharsets.UTF_8);
                try (InputStream safeIs = new ByteArrayInputStream(bytes)) {
                    answer = parseSecureDocument(safeIs);
                }
            } else if (body instanceof InputStream) {
                // Direct InputStream payload – parse it securely.
                try (InputStream safeIs = (InputStream) body) {
                    answer = parseSecureDocument(safeIs);
                }
