        // 3. Final resolution – if the caller did not request a specific type
        //    (type == null) we return the original body; otherwise we either
        //    return the successfully created document or re‑throw the original
        //    conversion exception.
        // -----------------------------------------------------------------
        if (type == null && answer == null) {
