import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.security.Principal;
import java.util.Objects;

/**
 * Determines whether a request to update a SCIM user is allowed.
 *
 * <p>
 * The original implementation only compared mutable fields (email, username, etc.) and
 * therefore allowed an attacker to impersonate another user by simply providing a different
 * email address in the request body.  The patched version adds a strict authorization check:
 * <ul>
 *   <li>The request must be authenticated (a {@link Principal} must be present).</li>
 *   <li>The authenticated principal's identifier must match the user ID extracted from the
 *       request URL, unless the caller has an administrative role (e.g. {@code uaa.admin}).</li>
 *   <li>All field comparisons now use {@link Objects#equals(Object, Object)} to avoid NPEs.</li>
 * </ul>
 * This ensures that only the owner of the account (or an admin) can perform a self‑update,
 * eliminating the impersonation vulnerability.
 * </p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Returns {@code true} if the request is allowed to update the user identified by the URL.
     *
     * @param request the incoming HTTP request
     * @return {@code true} if the update is permitted, {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1️⃣  Extract the JSON payload and deserialize it.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 2️⃣  Identify the target user from the URL.
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request)
        );
        String zoneId = IdentityZoneHolder.get().getId();

        // 3️⃣  Retrieve the persisted user (or treat a missing user as “allowed” – original behaviour).
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot enforce ownership – let the caller handle it.
            return true;
        }

        // 4️⃣  ---- AUTHORIZATION CHECK ----
        // Ensure the request is authenticated.
        Principal principal = request.getUserPrincipal();
        if (principal == null) {
            return false; // unauthenticated request
        }

        String authenticatedUserId = principal.getName(); // typically the SCIM user ID

        // Allow the operation if:
        //   a) the caller is the owner of the account (self‑update), or
        //   b) the caller possesses an administrative role.
        boolean isSelf = Objects.equals(authenticatedUserId, id);
        boolean isAdmin = request.isUserInRole("uaa.admin"); // role name used by UAA for admins

        if (!isSelf && !isAdmin) {
            return false; // neither owner nor admin – deny
        }

        // 5️⃣  ---- FIELD INTEGRITY CHECKS ----
        // The following fields must remain unchanged for a self‑update.
        // Using Objects.equals protects against NPEs.
        if (!Objects.equals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!Objects.equals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the update is allowed.
        return true;
    }

    // other methods (unchanged)
}
